/// @brief Enumeration for Cion errors.
/// @since_tizen 6.5
abstract class cion_error {
  /// < Success
  static const int CION_ERROR_NONE = 0;

  /// < I/O error
  static const int CION_ERROR_IO_ERROR = -5;

  /// < Out of memory
  static const int CION_ERROR_OUT_OF_MEMORY = -12;

  /// < Permission denied
  static const int CION_ERROR_PERMISSION_DENIED = -13;

  /// < Invalid parameter
  static const int CION_ERROR_INVALID_PARAMETER = -22;

  /// < Function not implemented
  static const int CION_ERROR_INVALID_OPERATION = -38;

  /// < Already in progress
  static const int CION_ERROR_ALREADY_IN_PROGRESS = -114;

  /// < Not supported
  static const int CION_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Timed out
  static const int CION_ERROR_TIMED_OUT = -1073741823;

  /// < Operation failed
  static const int CION_ERROR_OPERATION_FAILED = -51118079;
}

